];
const expected: Record<string, { decision: Decision; haiku55Usd: string | null; savingsBps: number | null }> = {
  "classify-short": { decision: "ALLOW", haiku55Usd: "0.000300", savingsBps: 9000 },
  "compact-under-limit": { decision: "ALLOW", haiku55Usd: "0.001450", savingsBps: 9000 },
  "compact-over-limit": { decision: "REVIEW", haiku55Usd: "0.015500", savingsBps: 5000 },
  "coding-short": { decision: "REVIEW", haiku55Usd: "0.001400", savingsBps: 9000 },
